WITH valid AS (SELECT *, CASE WHEN salary >= 163000 THEN 'High' WHEN salary >= 85000 THEN 'Medium' ELSE 'Low' END AS salary_level, COALESCE(full_name, 'unassigned') AS full_name_filled, COALESCE(job_title, 'DIRECT') AS job_title_filled FROM employees WHERE hire_date > DATE '2023-05-13' AND hire_date > '2023-07-01') SELECT dim.location, e.job_title, COUNT(*) AS rows_total, MAX(e.salary) AS max_salary FROM valid e INNER JOIN departments dim ON e.dept_id = dim.id GROUP BY GROUPING SETS ((dim.location, e.job_title), (dim.location), ()) ORDER BY max_salary NULLS LAST;
